package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.sql.Timestamp;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;
import io.knowledgebrain.contracts.collaboration.courseenrollment.v1.*;
/** Voluntary Course participation, visible to the participant and current Group OWNER. */
final class CourseEnrollmentStore {
 record Enrollment(UUID enrollmentId,UUID courseId,UUID groupId,UUID spaceId,UUID participantId,long version,String state,long courseVersion,String audience,String createdAt,String updatedAt) {}
 record LearningContext(UUID principalId,UUID groupId,UUID spaceId,UUID courseId,long courseVersion,String courseState,String role,UUID enrollmentId,long enrollmentVersion,String enrollmentState,List<CourseStore.StudyReference> studies) {}
 record Eligible(UUID principalId,long membershipVersion,UUID enrollmentId,long enrollmentVersion) {}
 record SharingContext(LearningContext learning,long policyVersion,boolean enabled,String audience,long membershipVersion,List<Eligible> eligibleParticipants) {}
 record Mine(Enrollment enrollment,String courseState,boolean canEnroll) {}
 record Summary(UUID enrollmentId,UUID participantId,long version,String state,long courseVersion,String updatedAt) {}
 record Page(List<Summary> items,UUID nextAfter) {}
 record Revision(UUID revisionId,long version,UUID actorId,String occurredAt,Enrollment snapshot) {}
 record History(List<Revision> items,Long nextBefore) {}
 private final JdbcTemplate sql;private final TransactionTemplate tx;private final CourseStore courses;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 CourseEnrollmentStore(DataSource source,CourseStore courses,Clock clock){sql=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));tx.setTimeout(15);this.courses=courses;this.clock=clock;ids=new UuidV7(clock);}
 private static ResponseStatusException error(HttpStatus status,String message){return new ResponseStatusException(status,message);}
 private String now(){return clock.instant().truncatedTo(ChronoUnit.MICROS).toString();}
 private Enrollment readMine(UUID group,UUID space,UUID course,UUID actor,boolean lock){var rows=sql.query("SELECT snapshot::text FROM course_enrollment WHERE group_id=? AND space_id=? AND course_id=? AND participant_id=?"+(lock?" FOR UPDATE":""),(rs,n)->json.readValue(rs.getString(1),Enrollment.class),group,space,course,actor);return rows.isEmpty()?new Enrollment(null,course,group,space,actor,0,"NOT_ENROLLED",0,"PARTICIPANT_AND_OWNER",null,null):rows.getFirst();}
 Mine mine(UUID group,UUID space,UUID course,UUID actor,boolean writer){var parent=courses.get(group,space,course);return new Mine(readMine(group,space,course,actor,false),parent.state(),writer&&parent.state().equals("ACTIVE"));}
 LearningContext learningContext(UUID group,UUID space,UUID course,UUID actor,String role){return tx.execute(s->{var parent=courses.lockForChild(group,space,course);var enrollment=readMine(group,space,course,actor,true);return new LearningContext(actor,group,space,course,parent.version(),parent.state(),role,enrollment.enrollmentId(),enrollment.version(),enrollment.state(),parent.studies());});}
 SharingContext sharingContext(UUID course,GroupSpaceClient.Sharing a){return tx.execute(s->{var p=courses.lockForChild(a.groupId(),a.spaceId(),course);var own=readMine(a.groupId(),a.spaceId(),course,a.principalId(),true);var eligible=new ArrayList<Eligible>();if(!a.activeMembers().isEmpty()){var versions=new HashMap<UUID,Long>();for(var m:a.activeMembers())versions.put(m.principalId(),m.membershipVersion());var args=new ArrayList<Object>();args.add(a.groupId());args.add(a.spaceId());args.add(course);args.addAll(versions.keySet());eligible.addAll(sql.query("SELECT participant_id,enrollment_id,version FROM course_enrollment WHERE group_id=? AND space_id=? AND course_id=? AND state='ENROLLED' AND participant_id IN ("+String.join(",",Collections.nCopies(versions.size(),"?"))+") ORDER BY participant_id",(rs,n)->new Eligible(rs.getObject(1,UUID.class),versions.get(rs.getObject(1,UUID.class)),rs.getObject(2,UUID.class),rs.getLong(3)),args.toArray()));}
  return new SharingContext(new LearningContext(a.principalId(),a.groupId(),a.spaceId(),course,p.version(),p.state(),a.role(),own.enrollmentId(),own.version(),own.state(),p.studies()),a.policyVersion(),a.enabled(),"OWNER",a.membershipVersion(),List.copyOf(eligible));});}
 static String input(byte[] bytes){var v=GroupInput.json(bytes);if(v==null||!v.isObject()||v.size()!=1||!v.path("state").isString()||!Set.of("ENROLLED","WITHDRAWN").contains(v.path("state").asString()))throw GroupInput.bad();return v.path("state").asString();}
 Enrollment change(UUID group,UUID space,UUID course,UUID actor,long expected,String state,String trace){
  for(var id:List.of(group,space,course,actor))GroupInput.id(id.toString());if(expected<0||state==null||!Set.of("ENROLLED","WITHDRAWN").contains(state)||trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw GroupInput.bad();
  return tx.execute(s->{var parent=courses.lockForChild(group,space,course);var old=readMine(group,space,course,actor,true);if(old.version()!=expected)throw error(HttpStatus.PRECONDITION_FAILED,"Enrollment changed; refresh current state");if(old.state().equals(state)||old.version()==0&&state.equals("WITHDRAWN"))return old;if(state.equals("ENROLLED")&&!parent.state().equals("ACTIVE"))throw error(HttpStatus.CONFLICT,"Only active Courses accept enrollment");
   String now=now();var v=new Enrollment(old.enrollmentId()==null?ids.next():old.enrollmentId(),course,group,space,actor,Math.addExact(old.version(),1),state,parent.version(),"PARTICIPANT_AND_OWNER",old.createdAt()==null?now:old.createdAt(),now);
   if(old.version()==0)sql.update("INSERT INTO course_enrollment (enrollment_id,course_id,group_id,space_id,participant_id,version,state,snapshot) VALUES (?,?,?,?,?,?,?,?::jsonb)",v.enrollmentId(),course,group,space,actor,v.version(),state,json.writeValueAsString(v));else sql.update("UPDATE course_enrollment SET version=?,state=?,snapshot=?::jsonb WHERE enrollment_id=?",v.version(),state,json.writeValueAsString(v),v.enrollmentId());record(v,trace);return v;
  });
 }
 Enrollment get(UUID group,UUID space,UUID course,UUID id,UUID actor,boolean owner){courses.get(group,space,course);var rows=sql.query("SELECT snapshot::text FROM course_enrollment WHERE group_id=? AND space_id=? AND course_id=? AND enrollment_id=?"+(owner?"":" AND participant_id=?"),(rs,n)->json.readValue(rs.getString(1),Enrollment.class),owner?new Object[]{group,space,course,id}:new Object[]{group,space,course,id,actor});if(rows.size()!=1)throw error(HttpStatus.NOT_FOUND,"Enrollment unavailable");return rows.getFirst();}
 Page list(UUID group,UUID space,UUID course,UUID after,int limit){courses.get(group,space,course);var rows=sql.query("SELECT enrollment_id,participant_id,version,state,(snapshot->>'courseVersion')::bigint,snapshot->>'updatedAt' FROM course_enrollment WHERE group_id=? AND space_id=? AND course_id=?"+(after==null?"":" AND enrollment_id>?")+" ORDER BY enrollment_id LIMIT ?",(rs,n)->new Summary(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getLong(3),rs.getString(4),rs.getLong(5),rs.getString(6)),after==null?new Object[]{group,space,course,limit+1}:new Object[]{group,space,course,after,limit+1});var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page(items,rows.size()>limit?items.getLast().enrollmentId():null);}
 History mineHistory(UUID group,UUID space,UUID course,UUID actor,long before,int limit){courses.get(group,space,course);var v=readMine(group,space,course,actor,false);return v.enrollmentId()==null?new History(List.of(),null):history(group,space,course,v.enrollmentId(),actor,false,before,limit);}
 History history(UUID group,UUID space,UUID course,UUID id,UUID actor,boolean owner,long before,int limit){get(group,space,course,id,actor,owner);var rows=sql.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM course_enrollment_revision WHERE enrollment_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Enrollment.class)),id,before,limit+1);var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new History(items,rows.size()>limit?items.getLast().version():null);}
 private void record(Enrollment v,String trace){
  sql.update("INSERT INTO course_enrollment_revision VALUES (?,?,?,?,?,?,?,?::jsonb)",ids.next(),v.enrollmentId(),v.version(),v.courseId(),v.courseVersion(),v.participantId(),Timestamp.from(Instant.parse(v.updatedAt())),json.writeValueAsString(v));
  var payload=CourseEnrollmentSnapshotV1.newBuilder().setEnrollmentId(v.enrollmentId().toString()).setCourseId(v.courseId().toString()).setGroupId(v.groupId().toString()).setSpaceId(v.spaceId().toString()).setParticipantId(v.participantId().toString()).setVersion(v.version()).setState(v.state()).setCourseVersion(v.courseVersion()).setAudience(v.audience()).setCreatedAt(v.createdAt()).setUpdatedAt(v.updatedAt()).build();UUID id=ids.next();String type=v.state().equals("ENROLLED")?"CourseEnrolled":"CourseWithdrawn";
  var e=CourseEnrollmentEnvelopeV1.newBuilder().setEventId(id.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(Instant.parse(v.updatedAt()).toEpochMilli()).setProducer("collaboration-service").setAggregateType("CourseEnrollment").setAggregateId(v.enrollmentId().toString()).setSpaceId(v.spaceId().toString()).setActorId(v.participantId().toString()).setTraceId(trace).setPayload(payload.toByteString()).build();sql.update("INSERT INTO outbox_event VALUES (?,'course-enrollment',?,?,?,?, 'collaboration','course-enrollment-events','1',?)",id,v.enrollmentId(),type,Timestamp.from(Instant.parse(v.updatedAt())),trace,e.toByteArray());
 }
}
